+        h: rowH,
+        fill: { color: fillColor },
+        line: border,
+      });
+      slide.addText(String(cell), {
+        x: curX + 0.12,
+        y: curY + 0.06,
+        w: colWidths[cIdx] - 0.24,
+        h: rowH - 0.12,
+        fontFace: theme.bodyFont,
+        fontSize: isHeader ? 12 : 11,
+        bold: isHeader,
+        color: isHeader ? headerColor : theme.ink,
+        align: cIdx === 0 ? 'left' : 'right',
+        valign: 'middle',
+        margin: 0,
+      });
+      curX += colWidths[cIdx];
+    });
+    curY += rowH;
+  });
+}
+
+function addSimpleBarChart(slide, theme, x, y, w, h, items, opts = {}) {
+  const maxVal = Math.max(...items.map((it) => it.value));
+  const leftPad = opts.leftPad ?? 1.35;
+  const rightPad = opts.rightPad ?? 0.25;
+  const topPad = opts.topPad ?? 0.2;
+  const bottomPad = opts.bottomPad ?? 0.25;
+
+  const plotX = x + leftPad;
+  const plotY = y + topPad;
+  const plotW = w - leftPad - rightPad;
+  const plotH = h - topPad - bottomPad;
+
+  // Axis baseline
+  slide.addShape(pptx.ShapeType.line, {
+    x: plotX,
+    y: plotY + plotH,
+    w: plotW,
+    h: 0,
+    line: { color: theme.grid, width: 2 },
+  });
+
+  const barGap = 0.12;
+  const barH = (plotH - barGap * (items.length - 1)) / items.length;
+  items.forEach((it, idx) => {
+    const barW = (it.value / maxVal) * plotW;
+    const barY = plotY + idx * (barH + barGap);
+    const barColor = it.color ?? theme.accent;
+    slide.addShape(pptx.ShapeType.roundRect, {
+      x: plotX,
+      y: barY,
+      w: barW,
+      h: barH,
+      fill: { color: barColor },
+      line: { color: barColor },
+      rectRadius: 0.12,
+    });
+    slide.addText(it.label, {
+      x: x,
+      y: barY + 0.02,
+      w: leftPad - 0.15,
+      h: barH,
+      fontFace: theme.bodyFont,
+      fontSize: 12,
+      color: theme.ink,
+      align: 'left',
+      valign: 'middle',
+      margin: 0,
+    });
+    slide.addText(`${it.value.toLocaleString()} TWh`, {
+      x: plotX + Math.min(barW + 0.08, plotW - 0.9),
+      y: barY + 0.02,
+      w: 0.9,
+      h: barH,
+      fontFace: theme.bodyFont,
+      fontSize: 11,
+      color: theme.ink,
+      align: 'left',
+      valign: 'middle',
+      margin: 0,
+    });
+  });
+}
