p=Presentation('/app/output/final_deck.pptx')
print('slides', len(p.slides))
for si,slide in enumerate(p.slides,1):
    texts=[]
    for shape in slide.shapes:
        if not hasattr(shape,'text_frame'):
            continue
        t=''.join([para.text for para in shape.text_frame.paragraphs]).strip()
        if t:
            texts.append((shape.left,shape.top,shape.width,shape.height,t[:60]))
    print('Slide',si,'textboxes',len(texts))
    for t in texts:
        if 'Global Renewable' in t[4] or 'How Far' in t[4]:
            print(' ',t)
PY""}

